        // 末尾追加低于最新值
        addReading("eq-mono", "m6", 4, "r4", "2026-01-01T13:00:00Z", 250, 422);
        // 边界相等允许（单调不减）
        addReading("eq-mono", "m7", 4, "r4", "2026-01-01T13:00:00Z", 300, 201);

        // 失败分支均未落库：共 4 条读数
