                        req.fromReadingId(), req.fromRevisionNo(),
                        req.toReadingId(), req.toRevisionNo(),
                        req.peakAt(), req.returnAt(), req.peakStressMpa(),
                        req.returnStressMpa(), damage, req.operator(), equipment.version() + 1);
