                 "fromReadingId":"r1","fromRevisionNo":1,"toReadingId":"r2","toRevisionNo":1,
                 "peakAt":"2026-01-01T11:00:00Z","returnAt":"2026-01-01T11:30:00Z",
                 "peakStressMpa":15,"returnStressMpa":10,"operator":"tester"}
                """;
